<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
require_once __DIR__.'/fixtures/NativeBusinessMutationFixture.php';
use DigiForge\Connector\Printify\{NativeProtectedOptionDependencies as Roots,NativeBusinessMutationEvidence as Evidence,NativeBusinessMutationAssociation as Association,NativeHeldJournalSchema};
use DigiForge\Database\Tables;
final class NativeSourceDataOptionCasTest extends WP_UnitTestCase {
 use NativeBusinessMutationFixture;
 private PrintifyApiApprovalFixture $fixture;private array $snapshots=[];
 protected function setUp():void{parent::setUp();remove_filter('query',[$this,'_create_temporary_tables']);remove_filter('query',[$this,'_drop_temporary_tables']);PortalAccessFixture::reset();DigiForge\Core\Activator::activate();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();global $wpdb;foreach([Tables::opportunities(),Tables::product_families(),Tables::products(),Tables::product_versions(),Tables::production_plans(),Tables::pod_mappings(),Tables::pod_business_mappings(),Tables::asset_specs(),Tables::production_plan_assets()]as $t)$this->snapshots[$t]=$wpdb->get_results('SELECT * FROM '.$t,ARRAY_A);DigiForge\Core\Settings::protectProduction();}
 protected function tearDown():void{try{global $wpdb;$wpdb->query('ROLLBACK');foreach(NativeHeldJournalSchema::tables()as $t)$wpdb->query('DROP TABLE IF EXISTS '.$t);foreach($this->snapshots as $t=>$rows){$wpdb->query('DELETE FROM '.$t);foreach($rows as $r)$wpdb->insert($t,$r,array_fill(0,count($r),'%s'));}$this->fixture->restore();}finally{parent::tearDown();}}
 public function testActualDataGettersFreezeExactBytesAndMissingDecisionPointersWithoutAuthority():void {
  self::assertTrue(class_exists(Roots::class),'Exact protected getter dependency capture and caller-owned option CAS required.');
  $f=$this->businessMutationFixture($this->fixture);$scope=$f['scope'];$m=$f['mapping_id'];$s=$f['spec_id'];$p=$f['plan_hash'];
  $capture=PrintifyApiApprovalFixture::checked(Roots::capture(static fn()=>Evidence::sourceMaterial($scope,1,$m,$s,$p)));
  $planKey='digiforge_pp_plan_'.$p;self::assertArrayHasKey($planKey,$capture['dependencies']);self::assertArrayHasKey('digiforge_product_package_'.$f['package_hash'],$capture['dependencies']);self::assertTrue($capture['dependencies'][$planKey]['exists']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/D',$capture['dependencies'][$planKey]['sha256']);self::assertStringNotContainsString('<svg',wp_json_encode($capture['dependencies']));
  $preparedPlan=PrintifyApiApprovalFixture::checked((new DigiForge\POD\PrintifyProductPipeline())->plan($p));$package=PrintifyApiApprovalFixture::checked((new DigiForge\POD\ProductPackageRepository())->read('personalized_pod',$f['package_hash']));$mediaPrefix='digiforge_s2_media_'.hash('sha256',$preparedPlan['workflow'].$package['record']['commercial_design_metadata']['design_hash']).'_';$mediaRoots=0;foreach($package['record']['evidence']['media']as $media){if(preg_match('~^shop2-mockups/([a-f0-9]{64})\.png$~D',$media['reference']??'',$match)){self::assertArrayHasKey($mediaPrefix.$match[1],$capture['dependencies'],'Exact validated supplier mockup bytes are source dependencies.');$mediaRoots++;}}self::assertSame(5,$mediaRoots);
  $source=PrintifyApiApprovalFixture::checked(Association::source($scope,1,$m,$s,$p));self::assertSame($capture['dependencies'],$source['data_option_dependencies']);
  global $wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->suppress_errors(true);$other->query('SET innodb_lock_wait_timeout=1');
  $proposal=PrintifyApiApprovalFixture::checked(Association::propose($scope,1,$m,$s,$p,$source['source_hash'],0,time(),time()+1200,wp_generate_uuid4()));PortalAccessFixture::login($this->fixture->reviewer);$held=false;$blocked=false;
  $hook=static function($q)use(&$held,&$blocked,$other,$planKey,$wpdb){if(!$held&&str_starts_with(ltrim($q),'INSERT')&&str_contains($q,'native_mutation_business_source_reviewed')){$held=true;$blocked=$other->query($other->prepare('UPDATE '.$wpdb->options.' SET option_value=CONCAT(option_value,%s) WHERE option_name=%s',' ',$planKey))===false&&str_contains($other->last_error,'Lock wait timeout');}return $q;};
  add_filter('query',$hook);try{$approved=PrintifyApiApprovalFixture::checked(Association::decide($scope,$this->fixture->reviewer,$m,$s,$p,$proposal['revision'],$proposal['proposal_hash'],'APPROVED',wp_generate_uuid4()));}finally{remove_filter('query',$hook);}self::assertTrue($held);self::assertTrue($blocked,'Actual review must retain the data-row fence until its own producer/audit commit.');self::assertSame('APPROVED',$approved['status']);
  $this->fixture->owner();$reviewed=PrintifyApiApprovalFixture::checked(Association::read($scope,1,$m,$s,$p));self::assertFalse($reviewed['source_approval_cas_verified']);self::assertNull($reviewed['native_product_version']);self::assertFalse($reviewed['dispatch_permitted']);
  $repo=new DigiForge\Research\OpportunityDesignRepository();$art=PrintifyApiApprovalFixture::checked($repo->read('personalized_pod',$capture['value']['evidence']['artwork_version_hash']));$input=$art['record']['input'];$input['title'].=' synthetic pending CAS';$pending=PrintifyApiApprovalFixture::checked($repo->save($input));self::assertNull($pending['approval']);
  $pendingCapture=PrintifyApiApprovalFixture::checked(Roots::capture(static fn()=>$repo->read('personalized_pod',$pending['version_hash'])));$versionKey='digiforge_opportunity_personalized_pod_'.$pending['version_hash'];$decisionKey=$versionKey.'_decision';self::assertSame(['exists'=>false,'sha256'=>null],$pendingCapture['dependencies'][$decisionKey]);
  self::assertWPError(Roots::lockCurrent($scope,1,$pendingCapture['dependencies']));self::assertNotFalse($wpdb->query('START TRANSACTION'));$locked=PrintifyApiApprovalFixture::checked(Roots::lockCurrent($scope,1,$pendingCapture['dependencies']));self::assertTrue($locked['source_data_options_locked']);self::assertFalse($locked['authority_roots_locked']);self::assertFalse($locked['source_approval_cas_verified']);self::assertFalse($locked['dispatch_permitted']);self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));
  self::assertFalse($other->query($other->prepare('UPDATE '.$wpdb->options.' SET option_value=CONCAT(option_value,%s) WHERE option_name=%s',' ',$versionKey)));self::assertStringContainsString('Lock wait timeout',$other->last_error);
  self::assertFalse($other->insert($wpdb->options,['option_name'=>$decisionKey,'option_value'=>'{}','autoload'=>'no'],['%s','%s','%s']));self::assertStringContainsString('Lock wait timeout',$other->last_error);
  self::assertNotFalse($wpdb->query('ROLLBACK'));self::assertSame(1,$other->query($other->prepare('UPDATE '.$wpdb->options.' SET option_value=CONCAT(option_value,%s) WHERE option_name=%s',' ',$versionKey)));self::assertSame(1,$other->insert($wpdb->options,['option_name'=>$decisionKey,'option_value'=>'{}','autoload'=>'no'],['%s','%s','%s']));
  self::assertNotFalse($wpdb->query('START TRANSACTION'));self::assertWPError(Roots::lockCurrent($scope,1,$pendingCapture['dependencies']));self::assertWPError(Roots::lockCurrent($scope,1,[$decisionKey=>['exists'=>false,'sha256'=>null]]));self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertNotFalse($wpdb->query('ROLLBACK'));$other->close();
  self::assertWPError(Roots::capture(static function(){Roots::observeOption('CLOUDFLARE_API_TOKEN','not-a-secret');return [];}));self::assertWPError(Roots::capture(static function()use($versionKey){Roots::observeOption($versionKey,'first');Roots::observeOption($versionKey,'second');return [];}));
  self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
}
